let department="All";
const departmentProducts=()=>products.filter(p=>department==="All"||p.department===department);
const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);const product=id=>products.find(p=>p.id===id);let cart=[];try{cart=JSON.parse(localStorage.getItem('noma-cart')||'[]').filter(x=>product(x.id)&&product(x.id).sizes.includes(x.size)&&!product(x.id).sold.includes(x.size)&&Number.isInteger(x.qty)&&x.qty>0).map(x=>({...x,qty:Math.min(x.qty,10)}))}catch{}let selectedSize='',currentProduct=null,filter='All pieces',sort='featured',returnFocus=null;const dialog=$('#drawer');

let saved=[];let viewed=[];let galleryIndex=0;
try{saved=[...new Set(JSON.parse(localStorage.getItem('noma-saved')||'[]'))].filter(id=>product(id));viewed=[...new Set(JSON.parse(localStorage.getItem('noma-viewed')||'[]'))].filter(id=>product(id))}catch{}
const heartIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.9a5.5 5.5 0 0 0-7.8 0L12 6l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.3a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
function saveButton(p,extra=''){return `<button class="save-piece ${extra} ${saved.includes(p.id)?'is-saved':''}" data-action="save" data-id="${p.id}" aria-pressed="${saved.includes(p.id)}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${p.name}">${heartIcon}</button>`}
function syncSaved(){try{localStorage.setItem('noma-saved',JSON.stringify(saved))}catch{}const counter=$('#saved-count');counter.textContent=saved.length;counter.hidden=!saved.length;document.querySelectorAll('[data-action="save"]').forEach(b=>{const active=saved.includes(b.dataset.id);b.classList.toggle('is-saved',active);b.setAttribute('aria-pressed',active);b.setAttribute('aria-label',`${active?'Unsave':'Save'} ${product(b.dataset.id).name}`)})}
function showSaved(){openDialog('Your saved pieces',saved.length?`<p class="small">Your favourites, saved in this browser.</p><div class="saved-list">${saved.map(id=>{const p=product(id);return `<article class="saved-row"><a href="#/product/${id}" data-action="close-link"><img src="assets/${p.image}.jpg" alt="${p.name}"></a><div><h3><a href="#/product/${id}" data-action="close-link">${p.name}</a></h3><p class="small">${p.color} · ${money(p.price)}</p><button class="text-link" data-action="quick" data-id="${id}">Choose size ↗</button></div>${saveButton(p)}</article>`}).join('')}</div>`:`<div class="empty"><span class="empty-heart">${heartIcon}</span><h3>Your saved pieces.</h3><p>Select the heart on any product to save it here.</p><a class="button" href="#/collection" data-action="close-link">Explore the collection ↗</a></div>`);dialog.dataset.panel='saved'}
function gallery(p){if(p.onModel)return [{src:p.image,label:'Styled on the body'}];return [{src:p.image,label:'Studio view'},{src:p.image==='bag'?'bag-editorial':'editorial',label:p.image==='bag'?'In the light':'On the body'},...(p.image==='bag'?[]:[{src:'hero',label:'The full look'}])]}
function galleryMarkup(p){return `<div class="product-gallery"><div class="detail-image"><button data-action="zoom" data-id="${p.id}" aria-label="Enlarge ${p.name} image"><img id="gallery-main" src="assets/${p.image}.jpg" alt="${p.name} — ${gallery(p)[0].label}" width="1024" height="1536"></button><span class="gallery-counter" id="gallery-counter">01 / ${String(gallery(p).length).padStart(2,'0')}</span><span class="zoom-hint">↗ &nbsp; VIEW CLOSER</span></div><div class="gallery-controls"><div class="gallery-thumbs" aria-label="Product image views">${gallery(p).map((g,i)=>`<button data-action="gallery" data-id="${p.id}" data-index="${i}" class="${i===0?'selected':''}" aria-pressed="${i===0}" aria-label="${g.label}"><img src="assets/${g.src}.jpg" alt="" loading="lazy"></button>`).join('')}</div><p class="small" id="gallery-caption">${gallery(p)[0].label}</p></div></div>`}
function recentMarkup(id){const ps=viewed.filter(x=>x!==id).slice(0,3).map(product);return ps.length?`<section class="recent-section section"><div class="section-head"><div><p class="eyebrow">YOUR RECENT PICKS</p><h2>Recently viewed.</h2></div></div><div class="recent-grid">${ps.map(p=>`<a class="recent-piece" href="#/product/${p.id}"><img src="assets/${p.image}.jpg" alt="${p.name}" loading="lazy"><div><h3>${p.name}</h3><p>${p.color}</p><span>${money(p.price)}</span></div><span>↗</span></a>`).join('')}</div></section>`:''}
function syncPurchaseBar(){const purchase=$('.detail-add'),sticky=$('.mobile-purchase');if(purchase&&sticky)sticky.classList.toggle('visible',purchase.getBoundingClientRect().bottom<80)}
let purchaseTick=false;window.addEventListener('scroll',()=>{if(!purchaseTick){purchaseTick=true;requestAnimationFrame(()=>{syncPurchaseBar();purchaseTick=false})}},{passive:true});window.addEventListener('resize',syncPurchaseBar);
function afterRender(){initHero();initSectionColour();syncSaved();document.querySelectorAll('.help-sidebar a').forEach(a=>{const active=a.getAttribute('href')===(location.hash==='#/care'?'#/care/delivery':location.hash);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(currentProduct&&location.hash.startsWith('#/product/')){viewed=[currentProduct.id,...viewed.filter(id=>id!==currentProduct.id)].slice(0,4);try{localStorage.setItem('noma-viewed',JSON.stringify(viewed))}catch{}}document.body.classList.toggle('product-route',!!$('.mobile-purchase'));requestAnimationFrame(syncPurchaseBar);document.querySelectorAll('header nav a').forEach(a=>{const active=a.getAttribute('href')===location.hash;a.classList.toggle('current',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});}

function persist(){try{localStorage.setItem('noma-cart',JSON.stringify(cart))}catch{}const count=cart.reduce((n,x)=>n+x.qty,0);$('#bag-count').textContent=count;$('#bag-count').hidden=count===0}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function openDialog(title,html){dialog.classList.remove('gallery-dialog');dialog.dataset.panel='';if(!dialog.open)returnFocus=document.activeElement;$('#drawer-title').textContent=title;$('#drawer-body').innerHTML=html;if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';dialog.querySelector('.close').focus()}
function closeDialog(){dialog.close();document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus()}
dialog.addEventListener('close',()=>{document.body.style.overflow=''});dialog.addEventListener('click',e=>{if(e.target===dialog&&e.clientX<dialog.getBoundingClientRect().left)closeDialog()});
function card(p){return `<article class="product-card"><div class="product-image"><a href="#/product/${p.id}" aria-label="View ${p.name}"><img class="card-front" src="assets/${p.image}.jpg" alt="${p.name} in ${p.color}" width="1024" height="1536" loading="lazy"></a><span class="product-tag">${p.tag}</span>${saveButton(p)}<button class="quick-add" data-action="quick" data-id="${p.id}" aria-label="Choose size for ${p.name}"><span>Choose size</span><b>+</b></button></div><div class="product-info"><div><h3><a href="#/product/${p.id}">${p.name}</a></h3><p><span class="color-dot" style="background:${p.hex}"></span>${p.color}<span class="product-department">${p.department==='Men'?'Menswear':'Womenswear'}</span></p></div><span class="price">${money(p.price)}</span></div></article>`}
const services=()=>`<section class="service-strip" aria-label="Collection philosophy"><div><b>CONSIDERED SILHOUETTES</b><p>Room to move. Space to be yourself.</p></div><div><b>A WARDROBE, TOGETHER</b><p>Women and men. Your own point of view.</p></div><div><b>DETAILS THAT MATTER</b><p>Texture, proportion, and a thoughtful finish.</p></div></section>`;
function styleStories(){const stories=[
{image:'denim',id:'straight-leg-denim',title:'Off the clock.',note:'Indigo denim, a striped layer, and an easy pace.',department:'Womenswear'},
{image:'men-overshirt',id:'men-overshirt',title:'Everyday layers.',note:'Olive cotton and clean neutrals for the weekend.',department:'Menswear'},
{image:'editorial',id:'sculpted-blazer',title:'A little structure.',note:'Relaxed tailoring with a softer point of view.',department:'Womenswear'},
{image:'men-blazer',id:'men-blazer',title:'An easy refinement.',note:'A navy blazer, a white tee, and nothing extra.',department:'Menswear'},
{image:'skirt',id:'pistachio-satin-skirt',title:'Into the evening.',note:'Fluid satin with understated styling.',department:'Womenswear'},
{image:'men-linen',id:'men-linen',title:'A warmer note.',note:'Terracotta linen and cream trousers, kept simple.',department:'Menswear'},
{image:'dress',id:'scarlet-midi-dress',title:'A little colour.',note:'A striking red dress with an easy sense of occasion.',department:'Womenswear'},
{image:'men-trousers',id:'men-trousers',title:'Relaxed proportions.',note:'Pleated sand trousers with a contrasting dark knit.',department:'Menswear'}
];return `<div class="style-stories blended-stories">${stories.map((x,i)=>`<a class="style-story" href="#/product/${x.id}"><div class="story-image"><img src="assets/${x.image}.jpg" alt="${product(x.id).name} styled as a complete outfit" loading="lazy"></div><span class="eyebrow">0${i+1} / ${x.department}</span><h3>${x.title} <span>↗</span></h3><p>${x.note}</p></a>`).join('')}</div>`}
const categoryNotes={Dresses:'Simple silhouettes with a distinctive point of view.',Shirts:'Crisp cotton, relaxed shapes, and considered colour.',Denim:'Easy proportions for everyday wear.',Skirts:'Fluid lines and a soft satin finish.',Tailoring:'Relaxed structure, from jackets to trousers.',Knitwear:'Soft layers that bring a wardrobe together.',Trousers:'Easy shapes with a considered finish.',Outerwear:'Light layers for wherever the day takes you.',Accessories:'The finishing details, thoughtfully chosen.'};
function home(){return `<section class="ambient-hero" aria-label="Collection highlights" aria-roledescription="carousel"><div class="ambient-images" aria-hidden="true"><div class="ambient-slide is-active" data-slide="0"><img src="assets/hero.jpg" alt="" fetchpriority="high" width="1536" height="1024"></div><div class="ambient-slide" data-slide="1"><img src="assets/men-blazer.jpg" alt="" width="1024" height="1536"></div><div class="ambient-slide" data-slide="2"><img src="assets/shirt.jpg" alt="" width="1024" height="1536"></div><div class="ambient-slide" data-slide="3"><img src="assets/men-overshirt.jpg" alt="" width="1024" height="1536"></div></div><div class="ambient-wash" aria-hidden="true"></div><div class="ambient-content"><p class="eyebrow">ATELIER NOMA / THE COLLECTION</p><h1>Considered clothing.<br>For everyday life.</h1><p>Modern tailoring, relaxed denim, and expressive separates.<br> Explore pieces that work together and feel like you.</p><div class="plain-hero-actions"><a class="button" href="#/collection">Explore the collection <span>↗</span></a><a class="text-link" href="#/look">Find your next look <span>↗</span></a></div></div><div class="ambient-controls"><div class="ambient-selector" aria-label="Choose a background look">${['Relaxed tailoring','Easy structure','Colour, confidently','Everyday layers'].map((name,i)=>`<button data-action="hero-slide" data-index="${i}" aria-label="Show ${name}" aria-pressed="${i===0}"><span></span></button>`).join('')}</div><a class="ambient-caption" id="ambient-caption" href="#/collection/Tailoring">01 / Relaxed tailoring <span>↗</span></a></div></section><section class="plain-section"><div class="plain-section-heading"><p class="eyebrow">01 / THE COLLECTION</p><h2>Shop by category.</h2></div><div class="category-directory">${Object.entries(categoryNotes).map(([name,description],i)=>`<a href="#/collection/${name}"><span class="directory-number">0${i+1}</span><div><h3>${name}</h3><p>${description}</p></div><span class="directory-arrow" aria-hidden="true">↗</span></a>`).join('')}</div></section><section class="plain-section plain-arrivals"><div class="plain-section-heading"><p class="eyebrow">02 / NEW ARRIVALS</p><h2>New arrivals.</h2><a class="text-link" href="#/collection">View the full collection ↗</a></div><div class="arrival-list">${[product('scarlet-midi-dress'),product('men-linen'),product('cobalt-poplin-shirt'),product('men-jacket')].map(p=>`<a href="#/product/${p.id}"><span><strong>${p.name}</strong><small>${p.department} · ${p.category} · ${p.color}</small></span><span>${money(p.price)} <b aria-hidden="true">↗</b></span></a>`).join('')}</div></section><section class="plain-section plain-about"><div><p class="eyebrow">03 / OUR APPROACH</p><h2>Our approach.</h2></div><div><p>One point of view, many ways to wear it. Our women’s and men’s collections share clean lines, thoughtful textures, and distinctive colour. Wear the pieces together, or make them part of the wardrobe you already love.</p><a class="text-link" href="#/story">About Atelier Noma <span>↗</span></a></div></section>`}

function collection(){return `<div class="page-title"><p class="eyebrow">CLOTHING & ACCESSORIES</p><h1>The collection.</h1><p>Explore clothing and accessories by category.<br>Find product details, available sizes, and styling ideas.</p></div><section class="section collection-section"><nav class="department-tabs" aria-label="Shop by department">${["All","Women","Men"].map(d=>`<a href="#/collection${d==="All"?"":"/"+d}" ${department===d?'aria-current="page"':''}>${d==="All"?"Shop all":d}</a>`).join('')}</nav><div class="collection-tools"><div class="filter-tabs" aria-label="Filter by category">${['All pieces',...new Set(departmentProducts().map(p=>p.category))].map(x=>`<button data-action="filter" data-filter="${x}" class="${filter===x?'active':''}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div><label class="small">Sort by <select id="sort"><option value="featured" ${sort==='featured'?'selected':''}>Featured</option><option value="low" ${sort==='low'?'selected':''}>Price: low to high</option><option value="high" ${sort==='high'?'selected':''}>Price: high to low</option></select></label></div><p class="small" id="result-count" role="status"></p><div class="product-grid" id="collection-grid"></div></section>${services()}`}
function updateCollection(){const title=filter==='All pieces'?(department==='All'?'The collection.':department==='Men'?'Menswear.':'Womenswear.'):(department==='All'?'':department+' / ')+filter+'.';$('.page-title h1').textContent=title;document.title=`${title.slice(0,-1)} — ATELIER NOMA`;let ps=departmentProducts().filter(p=>filter==='All pieces'||p.category===filter);if(sort==='featured'){const order=['scarlet-midi-dress','men-linen','cobalt-poplin-shirt','men-jacket','straight-leg-denim','men-denim','pistachio-satin-skirt','men-trousers','sculpted-blazer','men-blazer','pleated-trouser','men-overshirt','everyday-knit','men-knit','curve-shoulder-bag'];ps.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id))}if(sort==='low')ps.sort((a,b)=>a.price-b.price);if(sort==='high')ps.sort((a,b)=>b.price-a.price);$('#collection-grid').innerHTML=ps.map(card).join('');$('#result-count').textContent=`${ps.length} ${ps.length===1?'piece':'pieces'}${filter!=='All pieces'?' · '+filter:''}`}
function sizes(p){return `<div class="variant-section"><div class="variant-label"><span>Size <span id="selected-label">${selectedSize?'— '+selectedSize:''}</span></span><button class="back-link" data-action="size-guide" data-department="${p.department}" data-waist="${!!p.waistSizing}">Size guide</button></div><div class="size-options" aria-label="Choose size">${p.sizes.map(s=>`<button data-action="size" data-size="${s}" ${p.sold.includes(s)?'disabled':''} aria-label="${s}${p.sold.includes(s)?' — sold out':''}" aria-pressed="${selectedSize===s}" class="${selectedSize===s?'selected':''}">${s}</button>`).join('')}</div><p class="availability">${p.sold.length?'Crossed-out sizes are currently unavailable.':'Choose your preferred size.'}</p></div>`}
function detail(p){return `<section class="product-detail"><div class="breadcrumbs"><a href="#/collection">The collection</a> &nbsp;/&nbsp; ${p.name}</div><div class="product-layout">${galleryMarkup(p)}<div class="product-details"><div class="product-kicker"><p class="eyebrow">${p.department} / ${p.category} / ${p.onModel?'THE COLOUR EDIT':'THE FOUNDATIONS'}</p>${saveButton(p,'detail-save')}</div><h1>${p.name}</h1><p class="detail-price">${money(p.price)}</p><p class="product-description">${p.description}</p><div class="product-qualities"><span>${p.category==='Accessories'?'Sculptural form':'Considered proportions'}</span><span>${p.category==='Accessories'?'Tactile finish':'Soft by design'}</span></div><p class="small"><span class="color-dot" style="background:${p.hex}"></span> Colour — ${p.color}</p><div id="sizes">${sizes(p)}</div><button class="button wide detail-add" data-action="add" data-id="${p.id}"><span id="add-label">${selectedSize?'Add to bag':'Select a size'}</span><span>+</span></button><details open><summary>Composition & details</summary><p>${p.material}</p></details><details><summary>Size & fit</summary><p>${p.fit}</p></details><details><summary>Care for your piece</summary><p>${p.care}</p></details><details><summary>Delivery & returns</summary><p>See Customer care for delivery and return information. </p></details></div></div></section><section class="section product-complements" style="padding-top:10px"><div class="section-head"><div><p class="eyebrow">BETTER TOGETHER</p><h2>You may also like.</h2></div><a class="text-link" href="#/look">Shop the look ↗</a></div><div class="product-grid">${products.filter(x=>x.id!==p.id&&x.department===p.department).slice(0,4).map(card).join('')}</div></section>${recentMarkup(p.id)}<div class="mobile-purchase"><div><span>${p.name}</span><b>${money(p.price)}</b></div><button class="button" data-action="mobile-add" data-id="${p.id}">${selectedSize?'Add to bag':'Choose size'} +</button></div>`}
function look(){return `<div class="page-title"><p class="eyebrow">THE EVERYDAY WARDROBE</p><h1>Outfit ideas.</h1><p>Different perspectives. A shared sense of style.<br>Explore everyday looks and make them your own.</p></div><section class="section look-stories">${styleStories()}</section><section class="look-layout" id="tailoring-look"><div class="look-photo"><img src="assets/editorial.jpg" alt="The three-piece capsule styled together on a seated model" width="1024" height="1536"><span class="look-photo-caption">RELAXED TAILORING / LOOK 01</span></div><div class="look-builder"><p class="eyebrow">RELAXED TAILORING</p><h2 class="look-text">Build your look.</h2><p class="small">Select the pieces you want, choose a size for each,<br>and add them to your bag together.</p>${products.slice(0,3).map((p,i)=>`<article class="look-item" id="look-${p.id}"><input type="checkbox" checked data-look-check="${p.id}" aria-label="Include ${p.name}"><a href="#/product/${p.id}"><img src="assets/${p.image}.jpg" alt="${p.name}" loading="lazy"></a><div><span class="eyebrow">0${i+1} / ${p.color}</span><h3><a href="#/product/${p.id}">${p.name}</a></h3><p class="small">${money(p.price)}</p><label class="sr-only" for="look-size-${p.id}">Size for ${p.name}</label><select id="look-size-${p.id}"><option value="">Choose your size</option>${p.sizes.map(size=>`<option ${p.sold.includes(size)?'disabled':''} value="${size}">${size}${p.sold.includes(size)?' — sold out':''}</option>`).join('')}</select></div></article>`).join('')}<div class="look-summary"><div class="subtotal"><span id="look-count">3 selected pieces</span><strong id="look-total">${money(595)}</strong></div><button class="button" data-action="look-all">Add selected pieces to bag <span>+</span></button><p class="small" id="look-status" role="status">Choose an available size for each selected piece.</p></div></div></section>`}
function story(){return `<div class="page-title"><p class="eyebrow">ABOUT ATELIER NOMA</p><h1>Our story.</h1><p>Contemporary clothing with an individual point of view.</p></div><div class="story-layout"><div class="story-hero"><img src="assets/material.jpg" alt="Materials and tools at the atelier" width="1536" height="1024"></div><article class="story-copy"><p class="eyebrow">01 / OUR STARTING POINT</p><h2>What will you wear today?</h2><p>A cherry-red dress for no particular occasion. An olive overshirt for the weekend. A navy blazer that goes wherever the day takes you. Atelier Noma starts with a simple idea: getting dressed should feel like expressing yourself.</p><p>This collection pairs expressive colour with everyday foundations. Crisp poplin, indigo denim, liquid satin and soft tailoring make room for different moods. Wear one striking piece or mix a few together. There is more than one way to make it yours.</p><p class="eyebrow" style="margin-top:40px">02 / THE DETAILS</p><h2>Attention to the details.</h2><p>Look closer at the shoulder, the pleat, the curve of a handle. Our collection is built around these small decisions—the ones that make a familiar shape feel quietly distinctive.</p><a class="button" href="#/collection">Discover the collection ↗</a></article></div>`}
function sizeGuide(men=false,waist=false){if(waist)return `<p class="small">Trouser and denim sizes indicate waist in inches. Measure around your natural waist and compare below.</p><table class="size-table"><thead><tr><th>Size / waist (in)</th><th>Waist (cm)</th></tr></thead><tbody>${[28,30,32,34,36,38].map(n=>`<tr><td>${n}</td><td>${Math.round(n*2.54)}</td></tr>`).join('')}</tbody></table><p class="small">All sizes use a regular leg length. See each product’s fit notes for the cut.</p>`;if(men)return `<p class="small">Men’s body measurements in centimetres. Choose your usual size for a relaxed fit.</p><table class="size-table"><thead><tr><th>Size</th><th>Chest</th><th>Waist</th></tr></thead><tbody>${[["S",92,78],["M",98,84],["L",104,90],["XL",110,96],["XXL",116,102]].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="small">Measure around the fullest part of your chest and your natural waist.</p>`;return `<p class="small">Women’s body measurements in centimetres. Use this guide as a starting point and check the fit notes for each piece.</p><table class="size-table"><thead><tr><th>Size</th><th>Chest</th><th>Waist</th><th>Hip</th></tr></thead><tbody>${[['XS',80,62,88],['S',84,66,92],['M',90,72,98],['L',96,78,104],['XL',102,84,110]].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="small">Measure around the fullest part of your chest and hips, and the narrowest part of your waist. For fit notes, see each product page.</p>`}
function info(type){const content={care:['Delivery, returns & care.',`<h2 id="delivery">Delivery & returns</h2><p>Online ordering is currently unavailable. Delivery options and return terms will be provided when ordering opens.</p><h2 id="sizing">Size guide</h2>${sizeGuide()}<h2>Men’s size guide</h2>${sizeGuide(true)}<h2>Men’s trousers & denim</h2>${sizeGuide(true,true)}<h2 id="garment-care">Garment care</h2><details open><summary>Wool & knitwear</summary><p>Follow the care label on your garment. Air wool pieces between wears, dry knitwear flat, and store folded.</p></details><details><summary>Tailoring</summary><p>Store structured jackets on broad hangers. Read the individual product care notes before cleaning.</p></details><details><summary>Leather accessories</summary><p>Use a soft dry cloth, avoid prolonged moisture, and store away from direct sunlight.</p></details>`],contact:['Contact & support.',`<h2>How can we help?</h2><p>For sizing and garment care, start with our guides below. Direct customer support is currently unavailable.</p><p>For help exploring the collection, browse the size guide, product information, and garment-care notes.</p><a href="#/care/sizing" class="text-link">View the size guide ↗</a>`],privacy:['Privacy & terms.',`<h2>Your privacy</h2><p>Your shopping bag, saved pieces and recently viewed products are stored in this browser using local storage. The search operates entirely on the collection. The newsletter field does not transmit your email or create a subscription.</p><p>Fonts may be requested from Google Fonts. The hosting platform may process technical request information. </p><button class="button outline" data-action="clear-data">Clear saved browsing data</button><h2>Ordering</h2><p>Online ordering is currently unavailable. Adding items to your bag does not reserve stock or create an order. No payments are collected.</p>`]};let [title,html]=content[type];return `<div class="page-title"><p class="eyebrow">ATELIER NOMA / INFORMATION</p><h1>${title}</h1></div><div class="information-layout"><aside class="help-sidebar"><p class="eyebrow">CUSTOMER CARE</p><nav aria-label="Customer care navigation"><a href="#/care/delivery" ${type==='care'?'aria-current="page"':''}>Delivery & returns <span>↗</span></a><a href="#/care/sizing">Size guide <span>↗</span></a><a href="#/care/garment-care">Garment care <span>↗</span></a><a href="#/contact" ${type==='contact'?'aria-current="page"':''}>Contact & support <span>↗</span></a><a href="#/privacy" ${type==='privacy'?'aria-current="page"':''}>Privacy & terms <span>↗</span></a></nav><p class="help-note">Find your fit, explore the collection, and save your favourite pieces.</p></aside><article class="care-content">${html}</article></div>`}
function cartMarkup(){if(!cart.length)return `<div class="empty"><p class="eyebrow">YOUR SHOPPING BAG</p><h3>Your bag is empty.</h3><p>Explore the collection to add your first piece.</p><a class="button" href="#/collection" data-action="close-link">Explore the collection ↗</a></div>`;return `${cart.map((line,i)=>{const p=product(line.id);return `<article class="cart-line"><a href="#/product/${p.id}" data-action="close-link"><img src="assets/${p.image}.jpg" alt="${p.name}"></a><div><h3>${p.name}</h3><p>${p.color} / ${line.size}</p><span class="price">${money(p.price*line.qty)}</span><div><div class="quantity"><button data-action="quantity" data-index="${i}" data-change="-1" aria-label="Decrease quantity of ${p.name}" ${line.qty===1?'disabled':''}>−</button><span>${line.qty}</span><button data-action="quantity" data-index="${i}" data-change="1" aria-label="Increase quantity of ${p.name}" ${line.qty===10?'disabled':''}>+</button></div><button class="remove" data-action="remove" data-index="${i}" aria-label="Remove ${p.name}">Remove</button></div></div></article>`}).join('')}<div class="cart-summary"><div class="subtotal"><span>Subtotal</span><span>${money(cart.reduce((n,x)=>n+product(x.id).price*x.qty,0))}</span></div><p class="small">Prices in GBP.</p><button class="button wide" data-action="checkout">Checkout <span>↗</span></button><a class="text-link" href="#/cart" data-action="close-link">View full bag ↗</a><p class="demo-note">Online ordering is currently unavailable.</p></div>`}
function showCart(){openDialog('Your bag',cartMarkup())}
function add(id,size){let p=product(id);if(!p||!p.sizes.includes(size)||p.sold.includes(size)){toast('Please select an available size.');return false}let line=cart.find(x=>x.id===id&&x.size===size);if(line&&line.qty>=10){toast('Maximum 10 of this item in your bag.');return false}if(line)line.qty++;else cart.push({id,size,qty:1});persist();toast(`${p.name} added to your bag.`);return true}
function quick(id){currentProduct=product(id);selectedSize=currentProduct.sizes.length===1?'One size':'';openDialog('Choose your size',`<div style="display:flex;gap:20px;align-items:center"><img src="assets/${currentProduct.image}.jpg" alt="${currentProduct.name}" style="width:110px"><div><h3 style="font-size:28px">${currentProduct.name}</h3><p>${money(currentProduct.price)}</p><p class="small">${currentProduct.color}</p></div></div><div id="sizes">${sizes(currentProduct)}</div><button class="button wide" data-action="add" data-id="${id}"><span id="add-label">${selectedSize?'Add to bag':'Select a size'}</span><span>+</span></button><a href="#/product/${id}" data-action="close-link" class="text-link">View full details ↗</a>`)}
function searchResults(q){const ps=products.filter(p=>(['men','menswear','women','womenswear'].includes(q.toLowerCase().trim())?p.department===(q.toLowerCase().trim().startsWith('women')?'Women':'Men'):(p.name+' '+p.category+' '+p.color+' '+p.material).toLowerCase().includes(q.toLowerCase().trim())));$('#search-results').innerHTML=ps.length?ps.map(p=>`<a href="#/product/${p.id}" data-action="close-link" class="search-result"><img src="assets/${p.image}.jpg" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.color} · ${money(p.price)}</p></div><span style="margin-left:auto">↗</span></a>`).join(''):`<div class="empty"><h3>No pieces found.</h3><p>Try “cherry”, “denim”, “shirt” or “bag”.</p><button class="text-link" data-action="reset-search">Clear search ↗</button></div>`;$('#search-count').textContent=`${ps.length} ${ps.length===1?'piece':'pieces'} found`}
function render(){if(dialog.open)closeDialog();const path=(location.hash||'#/').slice(2).split('/');let html,title='A considered wardrobe';if(!path[0])html=home();else if(path[0]==='collection'){department=['Women','Men'].includes(path[1])?path[1]:'All';const category=department==='All'?path[1]:path[2];filter=departmentProducts().some(p=>p.category===decodeURIComponent(category||''))?decodeURIComponent(category):'All pieces';html=collection();title='The collection'}else if(path[0]==='product'&&product(path[1])){currentProduct=product(path[1]);selectedSize=currentProduct.sizes.length===1?'One size':'';galleryIndex=0;html=detail(currentProduct);title=currentProduct.name}else if(path[0]==='look'){html=look();title='Outfit ideas'}else if(path[0]==='story'){html=story();title='Our story'}else if(['care','contact','privacy'].includes(path[0])){html=info(path[0]);title=path[0]==='care'?'Customer care':path[0]==='contact'?'Contact & support':'Privacy & terms'}else if(path[0]==='cart'){html=`<div class="page-title"><p class="eyebrow">YOUR SELECTION</p><h1>Shopping bag.</h1></div><section class="full-cart" id="full-cart">${cartMarkup()}</section>`;title='Your bag'}else{html=`<div class="page-title"><p class="eyebrow">404 / PAGE NOT FOUND</p><h1>Page not found.</h1><p>This page isn’t part of the collection.</p><a href="#/collection" class="button">Explore the collection ↗</a></div>`;title='Page not found'}$('#main').innerHTML=html;document.title=`${title} — ATELIER NOMA`;if(path[0]==='collection')updateCollection();window.scrollTo({top:0,behavior:'instant'});afterRender();if(path[0]==='care'&&['delivery','sizing','garment-care'].includes(path[1]))document.getElementById(path[1])?.scrollIntoView();if(path[0]==='look'&&path[1]==='tailoring')document.getElementById('tailoring-look')?.scrollIntoView()}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}let el=e.target.closest('[data-action]');if(!el)return;let a=el.dataset.action,id=el.dataset.id;if(a==='close'||a==='close-link'){if(dialog.open)closeDialog()}if(a==='cart')showCart();if(a==='quick')quick(id);if(a==='menu')openDialog('Atelier Noma',`<nav class="mobile-nav" style="display:block" aria-label="Mobile navigation"><a href="#/collection" data-action="close-link">Shop all</a><a href="#/collection/Women" data-action="close-link">Women</a><a href="#/collection/Men" data-action="close-link">Men</a><a href="#/look" data-action="close-link">Outfit ideas</a><a href="#/story" data-action="close-link">Our story</a><a href="#/care" data-action="close-link">Customer care</a></nav><p class="small">Considered pieces. Unmistakably you.</p>`);if(a==='search'){openDialog('Search the collection',`<label for="search-field" class="sr-only">Search the collection</label><input class="search-input" id="search-field" placeholder="Try cherry, denim, shirt, or bag…" type="search"><p id="search-count" class="small" role="status"></p><div id="search-results"></div>`);searchResults('');$('#search-field').focus()}if(a==='reset-search'){$('#search-field').value='';searchResults('');$('#search-field').focus()}if(a==='size'){selectedSize=el.dataset.size;const scope=el.closest('.size-options');scope.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b.dataset.size===selectedSize);b.setAttribute('aria-pressed',b.dataset.size===selectedSize)});const root=dialog.open?$('#drawer-body'):$('.product-details');root.querySelector('#selected-label').textContent='— '+selectedSize;root.querySelector('#add-label').textContent='Add to bag';const hint=root.querySelector('.availability');if(hint?.classList.contains('selection-error')){hint.textContent='Size selected.';hint.classList.remove('selection-error')}if($('.mobile-purchase button'))$('.mobile-purchase button').textContent='Add to bag +' }if(a==='add'){const scope=dialog.open?dialog:$('.product-details');const chosen=scope.querySelector('[data-action="size"][aria-pressed="true"]');selectedSize=chosen?chosen.dataset.size:'';if(add(id,selectedSize))showCart();else{const scope=dialog.open?dialog:$('#main');const hint=scope.querySelector('.availability');if(hint){hint.textContent='Please choose an available size to add this piece.';hint.classList.add('selection-error')}scope.querySelector('.size-options button:not(:disabled)')?.focus()}}if(a==='look-add'){const s=$(`#look-size-${id}`);if(!s.value){toast('Choose a size for this piece.');s.focus()}else add(id,s.value)}if(a==='hotspot'){const target=$(`#look-${id}`);document.querySelectorAll('.look-item').forEach(x=>x.classList.remove('highlight'));target.classList.add('highlight');target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});$(`#look-size-${id}`).focus({preventScroll:true})}if(a==='size-guide')openDialog('Find your fit',sizeGuide(el.dataset.department==='Men',el.dataset.waist==='true'));if(a==='zoom'){const p=product(id);const g=gallery(p)[galleryIndex]||gallery(p)[0];openDialog(p.name,`<img class="zoom-image" src="assets/${g.src}.jpg" alt="${p.name} — ${g.label}"><p class="small">${p.color} · ${g.label}</p>`);dialog.classList.add('gallery-dialog')}if(a==='filter'){filter=el.dataset.filter;document.querySelectorAll('.filter-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)});updateCollection()}if(a==='quantity'||a==='remove'){let i=Number(el.dataset.index);if(a==='remove')cart.splice(i,1);else cart[i].qty=Math.max(1,Math.min(10,cart[i].qty+Number(el.dataset.change)));persist();if(dialog.open)$('#drawer-body').innerHTML=cartMarkup();if($('#full-cart'))$('#full-cart').innerHTML=cartMarkup();const root=dialog.open?dialog:$('#main');const focusTarget=root.querySelector(a==='quantity'?`[data-action="quantity"][data-index="${i}"][data-change="${el.dataset.change}"]:not(:disabled)`:'[data-action="remove"]');(focusTarget||root.querySelector('button,a'))?.focus();toast(a==='remove'?'Piece removed from your bag.':'Bag updated.')}if(a==='checkout')openDialog('Checkout',`<p class="eyebrow">YOUR SELECTION</p><h3 style="font-size:36px;line-height:1.1;margin:25px 0">Review your selection.</h3><p class="small">Online ordering is currently unavailable. Your selection is saved in this browser.</p><div class="subtotal" style="margin:30px 0"><span>Subtotal</span><span>${money(cart.reduce((n,x)=>n+product(x.id).price*x.qty,0))}</span></div><p class="demo-note">No order has been placed and no payment has been taken.</p><button class="button wide" data-action="cart" style="margin-top:30px">Return to your bag ↗</button>`);if(a==='clear-data'){cart=[];saved=[];viewed=[];persist();syncSaved();try{localStorage.removeItem('noma-viewed')}catch{}toast('Your bag, saved pieces and viewed history have been cleared.')}});
document.addEventListener('input',e=>{if(e.target.id==='search-field')searchResults(e.target.value)});document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;updateCollection()}});$('#newsletter').addEventListener('submit',e=>{e.preventDefault();$('#newsletter-status').textContent='Newsletter signup is currently unavailable. Your email has not been submitted.';$('#email').value=''});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action:a,id}=el.dataset;
if(a==='save'){const wasSaved=saved.includes(id);saved=wasSaved?saved.filter(x=>x!==id):[...saved,id];syncSaved();if(dialog.open&&dialog.dataset.panel==='saved')showSaved();toast(wasSaved?'Removed from your saved pieces.':'Saved for another look.');}
if(a==='saved')showSaved();
if(a==='look-all'){const chosen=[...document.querySelectorAll('[data-look-check]:checked')].map(c=>({p:product(c.dataset.lookCheck),size:document.getElementById('look-size-'+c.dataset.lookCheck).value}));if(!chosen.length){$('#look-status').textContent='Select at least one piece to build your look.';return}const missing=chosen.find(x=>!x.size);if(missing){$('#look-status').textContent=`Choose a size for ${missing.p.name}.`;document.getElementById('look-size-'+missing.p.id).focus();return}const capped=chosen.find(x=>cart.some(l=>l.id===x.p.id&&l.size===x.size&&l.qty>=10));if(capped){$('#look-status').textContent=`Your bag already has the maximum quantity of ${capped.p.name}.`;return}chosen.forEach(x=>add(x.p.id,x.size));showCart();toast(`${chosen.length} considered pieces added to your bag.`)}

if(a==='discover')$('#collection-preview')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
if(a==='gallery'){galleryIndex=Number(el.dataset.index);const p=product(id),g=gallery(p)[galleryIndex];$('#gallery-main').src=`assets/${g.src}.jpg`;$('#gallery-main').alt=`${p.name} — ${g.label}`;$('#gallery-counter').textContent=`${String(galleryIndex+1).padStart(2,'0')} / ${String(gallery(p).length).padStart(2,'0')}`;$('#gallery-caption').textContent=g.label;document.querySelectorAll('[data-action="gallery"]').forEach(b=>{const active=Number(b.dataset.index)===galleryIndex;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)})}
if(a==='mobile-add'){selectedSize=$('.product-details [data-action="size"][aria-pressed="true"]')?.dataset.size||'';if(selectedSize){if(add(id,selectedSize))showCart()}else{$('#sizes').scrollIntoView({behavior:'smooth',block:'center'});$('#sizes button[data-action="size"]:not(:disabled)')?.focus({preventScroll:true});toast('Choose your size to make it yours.')}}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-look-check]')){const chosen=[...document.querySelectorAll('[data-look-check]:checked')];$('#look-count').textContent=`${chosen.length} selected ${chosen.length===1?'piece':'pieces'}`;$('#look-total').textContent=money(chosen.reduce((sum,x)=>sum+product(x.dataset.lookCheck).price,0));$('#look-status').textContent=chosen.length?'Choose an available size for each selected piece.':'Select at least one piece to build your look.';document.querySelectorAll('[data-look-check]').forEach(c=>{document.getElementById('look-size-'+c.dataset.lookCheck).disabled=!c.checked})}});
let heroTimer=null,heroIndex=0,heroPaused=false;
const heroMotion=matchMedia('(prefers-reduced-motion: reduce)');
function setHeroSlide(index){const root=$('.ambient-hero');if(!root)return;heroIndex=index;root.querySelectorAll('.ambient-slide').forEach((el,i)=>el.classList.toggle('is-active',i===index));root.querySelectorAll('[data-action="hero-slide"]').forEach((el,i)=>el.setAttribute('aria-pressed',String(i===index)));const names=['Relaxed tailoring','Easy structure','Colour, confidently','Everyday layers'],urls=['#/collection/Tailoring','#/product/men-blazer','#/product/cobalt-poplin-shirt','#/product/men-overshirt'];const caption=$('#ambient-caption');caption.innerHTML=`0${index+1} / ${names[index]} <span>↗</span>`;caption.href=urls[index];root.dataset.tone=String(index)}
function updateHeroPause(){const root=$('.ambient-hero');if(root)root.classList.toggle('motion-paused',heroPaused)}
function initHero(){clearInterval(heroTimer);heroTimer=null;if(!$('.ambient-hero'))return;heroIndex=0;heroPaused=heroMotion.matches;setHeroSlide(0);updateHeroPause();heroTimer=setInterval(()=>{const root=$('.ambient-hero');if(root&&!heroPaused&&!document.hidden&&!dialog.open&&!root.matches(':focus-within'))setHeroSlide((heroIndex+1)%4)},3000)}
heroMotion.addEventListener('change',()=>{heroPaused=heroMotion.matches;updateHeroPause()});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;if(button.dataset.action==='hero-slide'){setHeroSlide(Number(button.dataset.index));heroPaused=true;updateHeroPause()}});
let sectionColourObserver;
function initSectionColour(){
  sectionColourObserver?.disconnect();
  const route=(location.hash||'#/').split('/')[1]||'home';
  const offsets={home:0,collection:1,product:2,look:3,story:4,care:1,contact:2,privacy:4,cart:0};
  const sections=[...document.querySelectorAll('#main > section:not(.ambient-hero), #main > .page-title, #main > .story-layout, #main > .information-layout, footer')];
  sectionColourObserver=new IntersectionObserver(entries=>{for(const entry of entries){entry.target.classList.toggle('colour-in-view',entry.isIntersecting);if(entry.isIntersecting)entry.target.classList.add('section-revealed')}},{threshold:0,rootMargin:'-8% 0px -8% 0px'});
  sections.forEach((section,i)=>{section.classList.add('colour-section');section.dataset.colour=String((i+(offsets[route]||0))%5);sectionColourObserver.observe(section)});
}
window.addEventListener('hashchange',render);persist();render();
